<?php use App\Core\Security;?><div class="card mb-3"><div class="card-body"><h5>واحدهای اندازه‌گیری</h5><form method="post" action="/pricing/public/admin/units" class="row g-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col"><input name="name" class="form-control" placeholder="نام واحد" required></div><div class="col"><input name="code" class="form-control" placeholder="کد"></div><div class="col-auto"><button class="btn btn-primary">ثبت</button></div></form></div></div><table class="table table-bordered"><tr><th>نام</th><th>کد</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($units as $u):?><tr><td colspan="4"><form method="post" action="/pricing/public/admin/units/<?=(int)$u['id']?>" class="row g-2 align-items-center"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col"><input name="name" value="<?=Security::e($u['name'])?>" class="form-control" required></div><div class="col"><input name="code" value="<?=Security::e($u['code'])?>" class="form-control"></div><div class="col-auto"><?=$u['is_active']?'فعال':'غیرفعال'?></div><div class="col-auto"><button class="btn btn-sm btn-outline-primary">ذخیره</button></div></form><?php if($u['is_active']):?><form method="post" action="/pricing/public/admin/units/<?=(int)$u['id']?>/archive" class="mt-1"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><button class="btn btn-sm btn-outline-danger">غیرفعال</button></form><?php endif;?></td></tr><?php endforeach;?></table>